function splitBatches(items, size) {
  const batches = [];
  for (let start = 0; start < items.length; start += size)
    batches.push(items.slice(start, start + size));
  return batches;
}

export default async ({ key, hour, portfolio }, context) => {
  if (!portfolio.rows.length) return { write: false, result: { state: "empty_portfolio", hour } };
  if (hour.endsWith("T00:00:00.000Z")) {
    const cutoff = new Date(Date.parse(hour) - 14 * 86400000).toISOString();
    const old = (await context.state.list()).filter(
      (id) => id.startsWith("portfolio:") && id.slice(10) < cutoff,
    );
    for (const group of splitBatches(old, 16)) {
      const saved = await context.state.get(group);
      for (const [i, record] of saved.entries())
        if (record?.state === "done") await context.state.delete(group[i]);
    }
  }
  if (await context.state.insert(key, { state: "pending" })) return { write: true, result: null };
  const saved = await context.state.get(key);
  if (saved?.state === "done")
    return { write: false, result: { ...saved, state: "already_recorded", hour } };
  throw new Error(
    "Airtable writes for " +
      hour +
      " are pending. Check the portfolio and history before retrying.",
  );
};

