  return rows.map(({ id, coinId }) => ({ id, fields: { "Present Price": prices[coinId] } }));
}

function splitBatches(items, size) {
  const batches = [];
  for (let start = 0; start < items.length; start += size)
    batches.push(items.slice(start, start + size));
  return batches;
}

export default ({ portfolio, quote }) => ({
  batches: splitBatches(recordsToUpdate(portfolio.rows, quote.prices), 10),
});

