function totalPortfolio(initial, completed, prices) {
  if (completed.length !== initial.length)
    throw new Error("The Airtable portfolio changed during pricing");
  const expected = new Map(initial.map((row) => [row.id, row.coinId]));
  let value = 0;
  for (const row of completed) {
    if (expected.get(row.id) !== row.coinId || row.price !== prices[row.coinId]) {
      throw new Error("The Airtable portfolio changed during pricing");
    }
    if (!Number.isFinite(row.value)) throw new Error("Present Value must be numeric for " + row.id);
    value += row.value;
  }
  if (!Number.isFinite(value)) throw new Error("The portfolio total is outside the numeric range");
  return value;
}

export default ({ before, after, quote }) => {
  const total = totalPortfolio(before.rows, after.rows, quote.prices);
  return { total, records: [{ fields: { "Portfolio Value (US$)": total } }] };
};

