function confirmSnapshot(records, total) {
  if (
    !Array.isArray(records) ||
    records.length !== 1 ||
    !/^rec[A-Za-z0-9]+$/.test(records[0]?.id ?? "") ||
    records[0].fields?.["Portfolio Value (US$)"] !== total
  ) {
    throw new Error("Airtable did not confirm the portfolio history append");
  }
  return records[0].id;
}

export default async ({ key, hour, records, total }, context) => {
  const airtableId = confirmSnapshot(records, total);
  const result = { state: "done", hour, total, airtableId };
  await context.state.set(key, result);
  return { result };
};
